        if (self->blk->owners == 0) {
            RefBlock* b = self->blk;
            b->destroy(b->obj);
            ::operator delete(self->blk);
        }
    }

    void* a = arg;
    self->blk = 0;
    self->obj = a;
    if (a) {
        RefBlock* b = (RefBlock*)::operator new(0xc);
        RefBlock* r;
        if (b) {
