    if (curBlk != rhsBlk)
    {
        if (curBlk != 0)
        {
            --curBlk->count;
            curBlk = self->blk;
            if (curBlk->count == 0)
            {
                curBlk->dtor(curBlk->ptr);
                curBlk = self->blk;
                ::operator delete(curBlk);
            }
        }

        self->obj = rhsObj;
        self->blk = rhsBlk;

